/// <summary>
/// PricingAttribute of table <c>InventTable</c> field TaxPackagingQty.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableTaxPackagingQty extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, TaxPackagingQty);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Real);
    InventTable inventTable;

    while select inventTable
        group by TaxPackagingQty
    {
        if (! ret.in(inventTable.TaxPackagingQty))
        {
            ret.add(inventTable.TaxPackagingQty);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, TaxPackagingQty));
    qbr.value(queryValue(_value));
}
